from dataclasses import dataclass


@dataclass(frozen=True)
class Category: slug: str; name: str; name_fa: str; description: str; description_fa: str
@dataclass(frozen=True)
class Tag: slug: str; name: str; name_fa: str
@dataclass(frozen=True)
class ArticleData:
    slug: str; category_slug: str; tag_slugs: tuple; product_slugs: tuple
    title: str; title_fa: str; summary: str; summary_fa: str
    content: str; content_fa: str; meta_title: str; meta_title_fa: str; meta_description: str; meta_description_fa: str

