def html(lead, sections, ending):
    parts = [f"<p><strong>{lead}</strong></p>"]
    for heading, text, points in sections:
        parts.extend((f"<h2>{heading}</h2>", f"<p>{text}</p>", "<ul>" + "".join(f"<li>{point}</li>" for point in points) + "</ul>"))
    is_fa = any("\u0600" <= char <= "\u06ff" for char in lead)
    shared = ([
        "<h2>اطلاعات محصول را بخشی از تصمیم بدانید</h2><p>فهرست فروشگاه و نمونه‌ها به محدودکردن گزینه‌ها کمک می‌کنند، اما تنها بخشی از تصمیم پروژه هستند. هنگام مقایسه، نام محصول، ابعاد، پرداخت سطح و اطلاعات فنی در دسترس را کنار هم نگه دارید تا مطمئن شوید کالای سفارش‌داده‌شده با محل استفاده هماهنگ است.</p><p>اگر پروژه شرایط ویژه، سطح موجود، برش‌های پیچیده، ابعاد بزرگ یا محل کاربرد دشوار دارد، از نصاب یا مشاور واجد شرایط بخواهید مصالح و سیستم دقیق را بررسی کند. یک راهنمای عمومی زیرکار و شرایط واقعی اجرا را نمی‌بیند.</p>",
        "<h2>انتخاب را قابل بررسی کنید</h2><p>پیش از سفارش، نمونه واقعی را در نور همان فضا و کنار مصالح اطراف ببینید. گزینه‌های در دسترس صفحه محصول را بررسی کنید و گونه و مقدار انتخاب‌شده را ثبت کنید. درباره چیدمان، برش‌های کناری، اتصال‌ها و مصالح پشتیبان پیش از شروع کار گفت‌وگو کنید.</p><ul><li>برچسب‌ها و اطلاعات سفارش را در پرونده پروژه نگه دارید.</li><li>کاربرد موردنظر را از مستندات فعلی سازنده تأیید کنید.</li><li>برای اتاق و زیرکار واقعی از تجربه اجرایی نصاب استفاده کنید.</li><li>پیش از بازکردن همه بسته‌ها، انتخاب نهایی را مرور کنید.</li></ul>",
    ] if is_fa else [
        "<h2>Use product information as part of the decision</h2><p>Store listings and samples help narrow choices, but they are only one part of a project decision. Keep the selected product name, size, finish, and available technical information together when comparing options. This makes it easier to confirm that the item being ordered matches the place where it will be used.</p><p>Where a project has unusual conditions, an existing surface, complex cuts, large formats, or a demanding location, ask a qualified installer or specifier to review the exact materials and system. A general guide cannot see the substrate, site conditions, or installation details.</p>",
        "<h2>Make the choice easier to review</h2><p>Before ordering, look at an actual sample in the intended light and alongside nearby finishes. Check the product page for the currently available options, then record the selected variant and quantity. Discuss layout, edge cuts, transitions, and supporting materials before work begins rather than after the tile arrives.</p><ul><li>Keep product labels and order details with the project records.</li><li>Confirm the intended use from the manufacturer’s current documentation.</li><li>Use the installer’s practical input for the actual room and substrate.</li><li>Review the final selection before opening all material.</li></ul>",
    ])
    closing = "پیش از تصمیم نهایی" if is_fa else "Before you decide"
    return "".join(parts + shared + [f"<h2>{closing}</h2><p>{ending}</p>"])

def article(slug, category, tags, products, title, title_fa, summary, summary_fa, en_sections, fa_sections):
    return ArticleData(slug, category, tuple(tags), tuple(products), title, title_fa, summary, summary_fa,
        html(summary, en_sections, "Use this guide to prepare questions, then confirm the intended use and technical information for the exact product and installation system."),
        html(summary_fa, fa_sections, "این راهنما برای آماده‌کردن پرسش‌هاست؛ کاربرد موردنظر و اطلاعات فنی همان محصول و سیستم نصب را پیش از تصمیم نهایی بررسی کنید."),
        title, title_fa, summary, summary_fa)

